import{_ as a,a0 as d,w as n,s as p,ao as r,I as i,x as e,a1 as l,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"高级 SSH 速查表 | LCTT x X-CMD","titleTemplate":false,"description":"高级 SSH 速查表 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"高级 SSH 速查表 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"高级 SSH 速查表 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180402 Advanced SSH Cheat Sheet","title":"高级 SSH 速查表","tag":"201804","desc":""},"relativePath":"201804/20180402 Advanced SSH Cheat Sheet.md","filePath":"[post].md"}'),g={name:"201804/20180402 Advanced SSH Cheat Sheet.md"};function c(h,t,k,u,f,b){const s=d("Link");return n(),p("div",null,[t[13]||(t[13]=r(`<h1 id="高级-ssh-速查表" tabindex="-1">高级 SSH 速查表 <a class="header-anchor" href="#高级-ssh-速查表" aria-label="Permalink to “高级 SSH 速查表”">​</a></h1><p>所有人都知道 SSH 是一种远程登录工具，然而它也有许多其他用途。</p><p>创建一个 SOCKS 代理来浏览网页（也就是翻墙啦）：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -D &lt;port&gt; &lt;remote_host&gt;</span></span></code></pre></div><p>设置 <code>localhost:&lt;port&gt;</code> 作为你浏览器的代理</p></blockquote><p>连接一个堡垒机后的 Windows RDP 主机：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -L &lt;port&gt;:&lt;target_host&gt;:3389 &lt;bastion_server&gt;</span></span></code></pre></div><p>让你的 RDP 客户端连接到 <code>localhost:&lt;port&gt;</code></p></blockquote><p>在不使用 VNC 端口的情况下，连接远程 VNC 主机：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -L 5901:localhost:5901 &lt;remote_host&gt;</span></span></code></pre></div><p>让你的 VNC 客户端连接到 <code>localhost:5901</code></p></blockquote><p>按照这个思路，你可以映射任意端口：LDAP (389)、631 (CUPS)、8080 (替代的 HTTP)，等等。</p><p>产生一个新的 SSH 密钥对：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen</span></span></code></pre></div></blockquote><p>更新密钥对的密码：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen -p</span></span></code></pre></div></blockquote><p>把公钥复制到远程主机上：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-copy-id -i &lt;identity file&gt; &lt;remote_host&gt;</span></span></code></pre></div></blockquote><p>SSH 有一堆命令行选项，但是如果有一些是你经常使用的，你可以为它们在 SSH 配置文件 (\${HOME}/.ssh/config) 里创建一个入口。比如：</p><blockquote><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host myhouse </span></span>
<span class="line"><span>   User itsme </span></span>
<span class="line"><span>   HostName house.example.com</span></span></code></pre></div></blockquote><p>那么你就可以输入 <code>ssh myhouse</code> 来代替 <code>ssh itsme@house.example.com</code>。</p><p>以下是常用的命令行选项和他们的配置文件写法。一些是常用的简化写法。请查看 <code>ssh(1)</code> 和 <code>ssh_config(5)</code> 的手册页来获取详尽信息。</p><div class="table-wrap"><table><thead><tr><th style="text-align:left;">命令行</th><th style="text-align:left;">配置文件</th><th style="text-align:left;">描述</th></tr></thead><tbody><tr><td style="text-align:left;"><code>-l &lt;login name&gt;</code></td><td style="text-align:left;"><code>User &lt;login name&gt;</code></td><td style="text-align:left;">远程主机的登录用户名。</td></tr><tr><td style="text-align:left;"><code>-i &lt;identity file&gt;</code></td><td style="text-align:left;"><code>IdentityFile &lt;identity file&gt;</code></td><td style="text-align:left;">指定要使用的鉴权文件（SSH 密码对）。</td></tr><tr><td style="text-align:left;"><code>-p &lt;remote port&gt;</code></td><td style="text-align:left;"><code>Port &lt;remote port&gt;</code></td><td style="text-align:left;">远程 SSH 守护进程监听的端口号。 (默认为 22)</td></tr><tr><td style="text-align:left;"><code>-C</code></td><td style="text-align:left;"><code>Compression &lt;yes,no&gt;</code></td><td style="text-align:left;">压缩往来信息。 (默认为 no)</td></tr><tr><td style="text-align:left;"><code>-D &lt;port&gt;</code></td><td style="text-align:left;"><code>DynamicForward &lt;port&gt;</code></td><td style="text-align:left;">把本地端口的报文转发到远程主机。</td></tr><tr><td style="text-align:left;"><code>-X</code></td><td style="text-align:left;"><code>ForwardX11 &lt;yes,no&gt;</code></td><td style="text-align:left;">把 X11 的图像数据转发到远程主机的端口. (默认为 no)</td></tr><tr><td style="text-align:left;"><code>-A</code></td><td style="text-align:left;"><code>ForwardAgent &lt;yes,no&gt;</code></td><td style="text-align:left;">把授权代理的报文转发给远程主机。如果你使用第三方主机登录，这个功能将很有用。 (默认为 no)</td></tr><tr><td style="text-align:left;"><code>-4</code>（仅使用 IPv4） <code>-6</code> （仅使用 IPv6）</td><td style="text-align:left;"><code>AddressFamily &lt;any,inet4,inet6&gt;</code></td><td style="text-align:left;">指定仅使用 IPv4 或者 IPv6。</td></tr><tr><td style="text-align:left;"><code>-L &lt;local port&gt;:&lt;target host&gt;:&lt;target port&gt;</code></td><td style="text-align:left;"><code>LocalForward &lt;local port&gt;:&lt;target host&gt;:&lt;target port&gt;</code></td><td style="text-align:left;">把本地主机指定端口的报文转发到远程主机的某个端口。</td></tr></tbody></table></div><p>opensource.com Twitter @opensourceway | facebook.com/opensourceway | IRC: #opensource.com on Freenode</p><hr><p>作者简介：</p><p>Ben Cotton 是业余的气象学家和职业的高性能计算工程师。Ben 是微软 Azure 的产品营销经理，专注于高性能计算。他是一个 Fedora 用户和贡献者，共同创立了一个当地的开放源码群，并且是开源促进会的成员和保护自由软件的支持者。通过以下方式联系他 Twitter (@FunnelFiasco) 或者 FunnelFiasco.com.</p><hr>`,25)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),l(s,{href:"https://opensource.com/sites/default/files/gated-content/cheat_sheet_ssh_v03.pdf"},{default:o(()=>[...t[0]||(t[0]=[e("https://opensource.com/sites/default/files/gated-content/cheat_sheet_ssh_v03.pdf",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),l(s,{href:"https://opensource.com/users/bcotton"},{default:o(()=>[...t[2]||(t[2]=[e("BEN COTTON",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),l(s,{href:"https://github.com/kennethXia"},{default:o(()=>[...t[3]||(t[3]=[e("kennethXia",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),l(s,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),l(s,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创编译，",-1)),l(s,{href:"https://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const S=a(g,[["render",c]]);export{x as __pageData,S as default};
